function debounce(fn, wait, options = {}) {
  const { leading = false, trailing = true } = options;
  let timer = null;
  let lastArgs = null;
  let lastThis = null;
  let result = null;

  function invoke() {
    const args = lastArgs;
    const context = lastThis;
    lastArgs = lastThis = null;
    result = fn.apply(context, args);
    return result;
  }

  function startTimer(pendingWait) {
    timer = setTimeout(timerExpired, pendingWait);
  }

  function timerExpired() {
    timer = null;
    if (trailing && lastArgs) {
      invoke();
    }
    lastArgs = lastThis = null;
  }

  function debounced(...args) {
    lastArgs = args;
    lastThis = this;
    const isInvoking = timer === null; // 是否是新一轮触发

    if (isInvoking && leading) {
      // leading 模式：首次触发立即执行
      invoke();
      // 但仍然设定时器，在 wait 内再次触发走防抖逻辑
    }

    // 清除旧定时器，重新开始倒计时
    if (timer !== null) clearTimeout(timer);
    startTimer(wait);

    return result;
  }

  debounced.cancel = function () {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    lastArgs = lastThis = null;
  };

  debounced.flush = function () {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
      return invoke();
    }
    return result;
  };

  return debounced;
}

// --- 使用示例 ---
// 搜索框：trailing 模式（默认），用户停止输入 300ms 后才发请求
const search = debounce(fetchSuggestions, 300);
input.addEventListener('input', (e) => search(e.target.value));

// 按钮：leading 模式，首次点击立即响应，防重复提交
const submit = debounce(doSubmit, 1000, { leading: true, trailing: false });
btn.addEventListener('click', submit);

// 组件卸载时取消：React useEffect cleanup
useEffect(() => {
  const handler = debounce(doSomething, 300);
  el.addEventListener('scroll', handler);
  return () => {
    handler.cancel(); // 必须 cancel，否则卸载后回调仍可能执行
    el.removeEventListener('scroll', handler);
  };
}, []);

function throttle(fn, wait, options = {}) {
  const { leading = true, trailing = true } = options;
  let timer = null;
  let lastArgs = null;
  let lastThis = null;
  let lastTime = 0; // 上次执行时间戳

  function invoke() {
    const args = lastArgs;
    const context = lastThis;
    lastArgs = lastThis = null;
    lastTime = Date.now();
    return fn.apply(context, args);
  }

  function timerExpired() {
    timer = null;
    const now = Date.now();
    const remaining = wait - (now - lastTime); // 距下次可执行还剩多久

    if (remaining <= 0) {
      // 间隔已满，可以执行尾部
      if (trailing && lastArgs) {
        invoke();
      } else {
        lastArgs = lastThis = null;
      }
    } else {
      // 间隔未满，补一个定时器等剩余时间
      timer = setTimeout(timerExpired, remaining);
    }
  }

  function throttled(...args) {
    const now = Date.now();
    lastArgs = args;
    lastThis = this;

    // 首次触发且不允许 leading：跳过立即执行，走定时器
    if (lastTime === 0 && !leading) {
      lastTime = now;
    }

    const remaining = wait - (now - lastTime);

    if (remaining <= 0) {
      // 已过间隔，立即执行
      if (timer !== null) {
        clearTimeout(timer);
        timer = null;
      }
      invoke();
    } else if (timer === null) {
      // 未过间隔且没有定时器，设一个等剩余时间
      timer = setTimeout(timerExpired, remaining);
    }
    // 其余情况：间隔未满且定时器已存在，直接丢弃本次调用

    return fn.__lastResult;
  }

  throttled.cancel = function () {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
    lastArgs = lastThis = null;
    lastTime = 0;
  };

  return throttled;
}

// --- 滚动监听：固定频率检查位置
window.addEventListener('scroll', throttle(checkPosition, 200));

// --- 拖拽更新：每 16ms 更新一次（约 60fps）
dragEl.addEventListener('mousemove', throttle(updateDrag, 16));
